select product_id, quantity_bucket, avg_quantity, revenue from (select product_id, case when quantity >= 7 then 'high' when quantity >= 2 then 'mid' else 'low' end as quantity_bucket, round(avg(quantity), 2) as avg_quantity, sum(unit_price * quantity) as revenue from order_items group by product_id, case when quantity >= 7 then 'high' when quantity >= 2 then 'mid' else 'low' end) as t where revenue < 35;
